## ---- 02: A Worked SMM Logit Example  (qmd line 355) ----------------------------------

# monthly_panel: loan-month rows with smm_event (0/1), coupon, prime,
# refi_incentive, age, sector, balance_log
monthly_panel <- read.csv("data/sample_monthly_panel.csv")

fit <- glm(smm_event ~ refi_incentive + age + I(age^2) +
           factor(sector) + balance_log,
           family = binomial(link = "cloglog"),
           data = monthly_panel)

summary(fit)

# Predict monthly SMM for a new loan-month record
new_data <- data.frame(refi_incentive = 0.005, age = 36,
                       sector = "54", balance_log = 13.0)
predicted_smm <- predict(fit, new_data, type = "response")


## ---- 03: Panel Fixed Effects with `plm`  (qmd line 399) ------------------------------

library(plm)

# Loan-month panel
fe_fit <- plm(log_smm ~ refi_incentive + age + I(age^2) + macro_index,
              data = monthly_panel,
              index = c("loan_id", "month_id"),
              model = "within")
summary(fe_fit)

# Hausman test FE vs RE
re_fit <- plm(log_smm ~ refi_incentive + age + I(age^2) + macro_index,
              data = monthly_panel,
              index = c("loan_id", "month_id"),
              model = "random")
phtest(fe_fit, re_fit)


## ---- 04: Logit and Probit via `glm`  (qmd line 419) ----------------------------------

library(splines)   # for ns()

fit_logit <- glm(prepay_event ~ refi_incentive + log(balance) +
                 factor(sector) + ns(age, df = 4),
                 family = binomial(link = "logit"),
                 data = monthly_panel)

fit_probit <- update(fit_logit, family = binomial(link = "probit"))
fit_cloglog <- update(fit_logit, family = binomial(link = "cloglog"))

# Marginal effects via mfx package
library(mfx); logitmfx(fit_logit, data = monthly_panel)


## ---- 05: Multinomial Logit (Competing Risks)  (qmd line 436) -------------------------

library(nnet)

fit_mlogit <- multinom(
  factor(event_type, levels = c("alive","prepay","default")) ~
    refi_incentive + macro_index + log(balance),
  data = monthly_panel
)
summary(fit_mlogit)


