## ---- 07: LASSO Variable Selection  (qmd line 461) ------------------------------------

library(glmnet)
library(broom)
library(ggplot2)

predictor_cols <- c("refi_incentive", "age", "balance_log",
                    "macro_index")
X <- model.matrix(~ . - 1, data = monthly_panel[, predictor_cols])
y <- monthly_panel$prepay_event

cv <- cv.glmnet(X, y, family = "binomial", alpha = 1)
coef(cv, s = "lambda.min")

cv_df <- tidy(cv)
ggplot(cv_df, aes(log(lambda), estimate)) +
  geom_errorbar(aes(ymin = conf.low, ymax = conf.high),
                colour = "grey70", width = 0.05) +
  geom_point(colour = "firebrick") +
  geom_vline(xintercept = log(c(cv$lambda.min, cv$lambda.1se)),
             linetype = 3) +
  labs(x = "log(lambda)", y = "Binomial deviance") +
  theme_minimal()


## ---- 08: Splines with `mgcv`  (qmd line 487) -----------------------------------------

