## ---- 10: Out-of-Time Validation  (qmd line 509) --------------------------------------

library(dplyr)

model_cols <- c("prepay_event", "refi_incentive", "age",
                "balance_log", "macro_index", "sector")
train <- monthly_panel %>% filter(year <= 2022) %>%
  select(all_of(model_cols)) %>% mutate(sector = factor(sector))
test  <- monthly_panel %>% filter(year >  2022) %>%
  select(all_of(model_cols)) %>% mutate(sector = factor(sector))

fit <- glm(prepay_event ~ ., family = binomial(link = "cloglog"),
           data = train)
test$pred <- predict(fit, test, type = "response")

library(pROC)
roc(test$prepay_event, test$pred)$auc


